text:
/* The creative report as a Claude dashboard, in the report's own brand. Only this page's .cr classes.
   The brand block carries the report template's tokens under the same names and values: each pair is
   light-dark(<light>, <dark>), so the host's colour scheme (it sets color-scheme on its root, for its own
   toggle and for the system setting) picks the report's light or dark value. A test keeps the two in step. */
.cr {
  --bg: light-dark(#ffffff, hsl(222 35% 5%));
  --surface: light-dark(#ffffff, hsl(222 28% 11%));
  --surface-raised: light-dark(#ffffff, hsl(222 28% 14%));
  --surface-muted: light-dark(hsl(210 40% 96.1%), hsl(222 25% 17%));
  --text: light-dark(hsl(222 47% 11%), hsl(210 20% 96%));
  --text-muted: light-dark(hsl(215 16% 47%), hsl(217 18% 68%));
  --border: light-dark(hsl(220 13% 91%), hsl(222 18% 29%));
  --accent: light-dark(hsl(251 97% 60%), hsl(251 91% 64%));
  --accent-soft: light-dark(hsl(251 97% 60% / .10), hsl(251 91% 64% / .16));
  --danger: light-dark(hsl(0 84% 60%), hsl(0 72% 55%));
  --bar: hsl(222 47% 8%);
  --bar-border: hsl(217 33% 18%);
  --bar-text: hsl(210 20% 96%);
  --bar-muted: hsl(217 18% 68%);
  --up-bg: light-dark(#dcfce7, hsl(160 84% 51% / .10));
  --up-fg: light-dark(#15803d, hsl(160 84% 51%));
  --down-bg: light-dark(#fee2e2, hsl(0 91% 71% / .10));
  --down-fg: light-dark(#b91c1c, hsl(0 91% 71%));
  --flat-bg: light-dark(hsl(220 13% 91%), hsl(222 25% 17%));
  --flat-fg: light-dark(hsl(220 9% 46%), hsl(217 18% 68%));
  --v-scale-bg: light-dark(#dbeafe, hsl(217 91% 60% / .12));
  --v-scale-fg: light-dark(#1d4ed8, hsl(217 91% 70%));
  --v-scale-bd: light-dark(#bfdbfe, hsl(217 91% 60% / .3));
  --v-keep-bg: light-dark(#ede9fe, hsl(258 90% 60% / .12));
  --v-keep-fg: light-dark(#6d28d9, hsl(258 90% 70%));
  --v-keep-bd: light-dark(#ddd6fe, hsl(258 90% 60% / .3));
  --v-iterate-bg: light-dark(#fef3c7, hsl(38 92% 60% / .12));
  --v-iterate-fg: light-dark(#b45309, hsl(38 92% 70%));
  --v-iterate-bd: light-dark(#fde68a, hsl(38 92% 60% / .3));
  --v-check-bg: light-dark(#e0f2fe, hsl(199 89% 60% / .12));
  --v-check-fg: light-dark(#0369a1, hsl(199 89% 70%));
  --v-check-bd: light-dark(#bae6fd, hsl(199 89% 60% / .3));
  --v-kill-bg: light-dark(#fee2e2, hsl(0 84% 60% / .12));
  --v-kill-fg: light-dark(#b91c1c, hsl(0 84% 70%));
  --v-kill-bd: light-dark(#fecaca, hsl(0 84% 60% / .3));
  --v-early-bg: light-dark(#f3f4f6, hsl(220 9% 46% / .12));
  --v-early-fg: light-dark(#4b5563, hsl(220 9% 70%));
  --v-early-bd: light-dark(#e5e7eb, hsl(220 9% 46% / .3));
  --v-cant-bg: light-dark(#f3f4f6, hsl(220 9% 46% / .12));
  --v-cant-fg: light-dark(#4b5563, hsl(220 9% 70%));
  --v-cant-bd: light-dark(#e5e7eb, hsl(220 9% 46% / .3));
  --tone-scale-bd: light-dark(#86efac, hsl(160 84% 51% / .4));
  --tone-scale-bg: light-dark(rgb(240 253 244 / .6), hsl(160 84% 51% / .06));
  --tone-warn-bd: light-dark(#fcd34d, hsl(38 92% 50% / .4));
  --tone-warn-bg: light-dark(rgb(255 251 235 / .6), hsl(38 92% 50% / .06));
  --series-1: #6366f1;
  --series-2: #16a34a;
  --series-3: #f59e0b;
  --series-4: #f43f5e;
  --series-5: #06b6d4;
  --series-6: #d946ef;
  --series-neutral: #64748b;
  --series-other: #b4bcc8;
  --shadow: 0 1px 2px light-dark(rgb(0 0 0 / .05), rgb(0 0 0 / .4));
  --hover-border: hsl(251 97% 60% / .4);
  --hover-shadow: 0 4px 12px hsl(251 97% 60% / .08);
  --space-half: 2px;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-7: 32px;
  --space-8: 40px;
  --space-9: 56px;
  --nav-w: 208px;
  --pad-panel: var(--space-5);
  --pad-card: var(--space-4);
  --gap-cards: var(--space-4);
  --radius-xs: 4px;
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 14px;
  --radius-pill: 999px;
  --success: #059669;
  --error: #dc2626;
  --warning: #e8ad00;
  --info: #343CED;
  --ink-500: #6b6889;
  --ink-900: #0a0227;
  --page: var(--bg);
  --surface-soft: var(--surface-muted);
  --heading: var(--text);
  --body: var(--text-muted);
  --divider: var(--border);
  --accent-text: var(--accent);
  --chip-bg: var(--accent-soft);
  --violet-accent: var(--accent);
  --violet-button: var(--accent);
  --focus: var(--accent);
  --font-body: "DM Sans", var(--font-anthropic-sans), system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-head: var(--font-body);
  --font-mono: "Roboto Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  /* The dashboard's own chart tokens: one hue per format, the same in both themes and clear of the verdict hues (violet, blues, amber, rose), and marks strong enough in dark mode. */
  --fmt-1: light-dark(hsl(175 70% 30%), hsl(172 60% 52%));
  --fmt-2: light-dark(hsl(320 55% 42%), hsl(320 60% 72%));
  --fmt-3: light-dark(hsl(70 60% 32%), hsl(66 55% 58%));
  --fmt-4: light-dark(hsl(215 25% 42%), hsl(215 25% 70%));
  --fmt-5: light-dark(hsl(145 55% 32%), hsl(145 45% 58%));
  --fmt-6: light-dark(hsl(20 45% 38%), hsl(20 50% 66%));
  --fmt-7: light-dark(hsl(100 45% 42%), hsl(100 40% 66%));
  --band: light-dark(hsl(251 97% 60% / .14), hsl(251 91% 72% / .26));
  --bars: light-dark(hsl(215 20% 65% / .55), hsl(217 20% 60% / .45));
  --scope-bg: light-dark(hsl(210 40% 96.1%), var(--bar));
  --scope-border: light-dark(hsl(220 13% 88%), var(--bar-border));
  --scope-text: light-dark(hsl(222 47% 11%), var(--bar-text));
  --scope-muted: light-dark(hsl(215 16% 42%), var(--bar-muted));
}

/* ---------- page and header ---------- */
.cr, .cr *, .cr *::before, .cr *::after { box-sizing: border-box; }
.cr { display: flex; flex-direction: column; gap: var(--space-5); max-width: 1536px; margin-inline: auto; min-width: 0;
  font: 400 15px/1.5 var(--font-body); color: var(--text); font-variant-numeric: tabular-nums; }
.cr-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.cr-head { display: flex; flex-direction: column; gap: var(--space-2); min-width: 0; }
.cr-bar { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); min-height: 40px; margin-bottom: var(--space-3); }
.cr-lockup { display: flex; align-items: center; gap: var(--space-3); min-width: 0; }
.cr-logo { display: block; height: 28px; width: auto; }
.cr-logo-dark, .cr.cr-dark .cr-logo-light { display: none; }
.cr.cr-dark .cr-logo-dark { display: block; }
.cr-brand-div { width: 1px; height: 22px; background: var(--divider); }
.cr-brand-by { font: 600 12px/1 var(--font-head); color: var(--body); }
.cr-status { margin: 0; padding: var(--space-1) var(--space-3); border-radius: var(--radius-pill); font: 600 12px/1.3 var(--font-head); white-space: nowrap;
  background: var(--flat-bg); color: var(--flat-fg); cursor: help; }
.cr-status.cr-tone-ok { background: var(--accent-soft); color: var(--accent-text); }
.cr-status.cr-tone-warn { background: var(--warning); color: var(--ink-900); }
.cr-eyebrow { margin: 0; font: 600 12px/1 var(--font-head); letter-spacing: .08em; text-transform: uppercase; color: var(--accent); }
.cr-title { margin: 0; font: 600 28px/1.2 var(--font-head); letter-spacing: -0.01em; color: var(--heading); overflow-wrap: anywhere; }
.cr-lead { margin: 0; max-width: 72ch; font-size: 16px; line-height: 1.5; color: var(--heading); }
.cr-lead-card { margin-top: var(--space-1); }
.cr-scope { display: flex; flex-wrap: wrap; margin: var(--space-3) 0 0; padding: var(--space-1) 0; border-radius: var(--radius-lg); background: var(--scope-bg);
  color: var(--scope-text); border: 1px solid var(--scope-border); }
.cr-scope-seg { display: flex; align-items: baseline; gap: var(--space-2); padding: var(--space-2) var(--space-4); border-right: 1px solid var(--scope-border); font-size: 14px; min-width: 0; }
.cr-scope-seg:last-child { border-right: 0; }
.cr-scope-seg dt { font-size: 13px; color: var(--scope-muted); }
.cr-scope-seg dd { margin: 0; font-weight: 600; overflow-wrap: anywhere; }

/* ---------- tabs and the date range ---------- */
.cr-sticky { position: sticky; top: 0; z-index: 4; display: flex; flex-wrap: wrap; align-items: stretch; gap: var(--space-3) var(--space-4);
  padding: var(--space-2) 0 var(--space-3); background: var(--color-bg); border-bottom: 1px solid var(--border); }
.cr-tabs { display: flex; align-self: center; gap: var(--space-half); padding: var(--space-1); border-radius: var(--radius); background: var(--surface-muted); overflow-x: auto; scrollbar-width: none; max-width: 100%; }
.cr-tabs a { flex: none; padding: var(--space-2) var(--space-3); border-radius: var(--radius-sm); color: color-mix(in srgb, var(--text) 78%, var(--surface-muted)); text-decoration: none; font: 500 13px/1.3 var(--font-body); white-space: nowrap; }
.cr-tabs a:hover { color: var(--text); }
.cr-tabs a:focus-visible { outline: 2px solid var(--focus); outline-offset: 1px; }
.cr-tabs a[aria-current="true"] { background: var(--surface-raised); color: var(--accent); box-shadow: 0 1px 3px rgb(0 0 0 / .08); font-weight: 600; }
.cr-range { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "head fields" "brush brush"; align-items: center; gap: var(--space-1) var(--space-3);
  flex: 1 1 420px; min-width: 0; padding: var(--space-2) var(--space-3); border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface);
  font-size: 13px; color: var(--text-muted); }
.cr-range[hidden] { display: none; }
.cr-range-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--space-1) var(--space-2); min-width: 0; }
.cr-range-label { font: 600 12px/1 var(--font-head); letter-spacing: .06em; text-transform: uppercase; color: var(--heading); }
.cr-range-hint { font-size: 12px; }
.cr-range-fields { grid-area: fields; display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: var(--space-2); }
.cr-range-to { font-size: 12px; }
.cr-range-off { flex: 1 1 420px; display: flex; align-items: center; box-sizing: border-box; margin: 0; padding: var(--space-2) 0; font-size: 12.5px; color: var(--text-muted); }
.cr-range-off[hidden] { display: none; }
.cr-date { font: 500 12.5px/1.2 var(--font-mono); color: var(--text); background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-sm);
  padding: var(--space-1) var(--space-2); min-width: 0; color-scheme: inherit; }
.cr-date:focus-visible { outline: 2px solid var(--focus); outline-offset: 1px; }
.cr-brush { grid-area: brush; position: relative; min-width: 0; height: 40px; }
.cr-brush svg { display: block; }
.cr-brush .selection { fill: var(--accent); fill-opacity: .14; stroke: var(--accent); stroke-width: 1; shape-rendering: crispEdges; }
.cr-brush .handle { fill: var(--accent); fill-opacity: .9; rx: 2; }
.cr-brush .overlay { cursor: crosshair; }
.cr-brush .cr-brush-end { font: 500 10.5px/1 var(--font-mono); fill: var(--text-muted); }
.cr-reset { font: 600 12px/1 var(--font-head); color: var(--accent); background: var(--accent-soft); border: 0; border-radius: var(--radius-pill); padding: var(--space-2) var(--space-3); cursor: pointer; white-space: nowrap; }
.cr-range-note { color: var(--accent-text); font-weight: 600; }
.cr-whole, .cr-whole-inline { color: var(--accent-text); font-size: 12.5px; font-weight: 600; }
.cr-whole { margin: 0; }

/* ---------- pages and cards ---------- */
.cr-page { display: flex; flex-direction: column; gap: var(--gap-cards); min-width: 0; scroll-margin-top: 72px; }
.cr-page[hidden] { display: none; }
.cr-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); padding: var(--pad-panel);
  display: flex; flex-direction: column; gap: var(--space-3); min-width: 0; }
.cr-card[hidden] { display: none; }
.cr-card-head { display: flex; flex-direction: column; gap: var(--space-2); }
.cr-h3 { margin: 0; font: 600 20px/1.2 var(--font-head); letter-spacing: -0.01em; color: var(--heading); }
.cr-h4 { margin: var(--space-4) 0 0; font: 600 15px/1.3 var(--font-head); color: var(--heading); }
.cr-h5 { margin: var(--space-3) 0 0; font: 600 13px/1.3 var(--font-head); letter-spacing: .04em; text-transform: uppercase; color: var(--text-muted); }
.cr-note, .cr-muted { margin: 0; font-size: 13px; color: var(--text-muted); max-width: 90ch; }
.cr-muted[hidden], .cr-note[hidden] { display: none; }
.cr-empty { margin: 0; padding: var(--pad-card); border: 1px dashed var(--divider); border-radius: var(--radius); background: var(--surface-soft); color: var(--text-muted); font-size: 13.5px; }
.cr-failed { display: flex; align-items: center; justify-content: center; gap: var(--space-2); color: var(--text-muted); font-size: 12px; min-height: inherit; }
.cr-failed::before { content: ""; width: 0.375rem; height: 0.375rem; border-radius: 50%; background: var(--error); }
.cr-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 30rem), 1fr)); gap: var(--gap-cards); }
.cr-gone { margin: 0; font-size: 13px; color: var(--text-muted); }
.cr-gone[hidden] { display: none; }
.cr-gone-title { cursor: pointer; width: fit-content; }
.cr-gone-title::marker { color: var(--warning); }
.cr-gone .cr-list { margin-top: var(--space-2); font-size: 13px; }
.cr-list { margin: 0; padding-left: var(--space-5); display: flex; flex-direction: column; gap: var(--space-1); font-size: 13.5px; color: var(--body); }
.cr-method { font-size: 13px; }

/* ---------- switches, pills and tools ---------- */
.cr-toolbar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-2) var(--space-3); }
.cr-seg { display: inline-flex; flex-wrap: wrap; max-width: 100%; gap: var(--space-half); padding: var(--space-1); border-radius: var(--radius-lg); background: var(--surface-muted); width: fit-content;
  max-width: 100%; overflow-x: auto; scrollbar-width: none; }
.cr-seg[hidden], .cr-pills[hidden], .cr-tools[hidden] { display: none; }
.cr-seg button { flex: none; font: 600 12.5px/1 var(--font-head); padding: var(--space-2) var(--space-3); border-radius: var(--radius-pill); border: 0; background: transparent;
  color: var(--text-muted); cursor: pointer; white-space: nowrap; }
.cr-seg button[aria-pressed="true"] { background: var(--surface); color: var(--heading); box-shadow: var(--shadow); }
.cr-seg button:focus-visible, .cr-pills button:focus-visible, .cr-more:focus-visible { outline: 2px solid var(--focus); outline-offset: 1px; }
.cr-pills { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.cr-pills button { display: inline-flex; align-items: center; gap: var(--space-2); font: 600 12.5px/1 var(--font-head); padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-pill); border: 1px solid var(--border); background: var(--surface); color: var(--text-muted); cursor: pointer; white-space: nowrap; }
.cr-pills button[aria-pressed="true"] { border-color: var(--accent); color: var(--heading); background: var(--accent-soft); }
.cr-count { font: 500 11.5px/1 var(--font-mono); color: var(--text-muted); }
.cr-tools { display: flex; flex-wrap: wrap; gap: var(--space-2); flex: 1 1 280px; justify-content: flex-end; }
.cr-search, .cr-select { font: 500 13px/1.2 var(--font-body); color: var(--text); background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-sm);
  padding: var(--space-2) var(--space-3); min-width: 0; color-scheme: inherit; }
.cr-search { flex: 1 1 200px; max-width: 320px; }
.cr-search:focus-visible, .cr-select:focus-visible { outline: 2px solid var(--focus); outline-offset: 1px; }
.cr-more-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-2); }
.cr-more { font: 600 13px/1 var(--font-head); color: var(--accent); background: var(--accent-soft); border: 0; border-radius: var(--radius-pill); padding: var(--space-2) var(--space-4); cursor: pointer; }
.cr-more[hidden] { display: none; }

/* ---------- key numbers ---------- */
.cr-kpis { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 13rem), 1fr)); gap: var(--space-3); }
.cr-kpis[hidden] { display: none; }
.cr-kpi { display: flex; flex-direction: column; gap: var(--space-1); border: 1px solid var(--border); border-radius: var(--radius); padding: var(--space-3) var(--pad-card); background: var(--surface);
  box-shadow: var(--shadow); min-width: 0; transition: border-color .25s ease, box-shadow .25s ease; }
.cr-kpi:hover { border-color: var(--hover-border); box-shadow: var(--hover-shadow); }
.cr-kpi p { margin: 0; }
.cr-kpi.cr-unknown { order: 1; background: var(--surface-soft); box-shadow: none; }
.cr-kpi-name { font: 600 12px/1.3 var(--font-body); letter-spacing: .04em; text-transform: uppercase; color: var(--text-muted); }
.cr-kpi-value { font: 500 23px/1.2 var(--font-mono); letter-spacing: -0.01em; color: var(--text); overflow-wrap: anywhere; }
.cr-kpi.cr-unknown .cr-kpi-value { color: var(--text-muted); font-size: 16px; }
.cr-kpi-change { width: fit-content; padding: var(--space-half) var(--space-2); border-radius: var(--radius-pill); font: 600 12px/1.4 var(--font-body); }
.cr-kpi-change.cr-up { background: var(--up-bg); color: var(--up-fg); }
.cr-kpi-change.cr-down { background: var(--down-bg); color: var(--down-fg); }
.cr-kpi-change.cr-flat { background: var(--flat-bg); color: var(--flat-fg); }
.cr-kpi-note { font-size: 12px; color: var(--text-muted); }
.cr-spark { margin-top: auto; padding-top: var(--space-2); min-height: 48px; }
.cr-spark[hidden] { display: none; }
.cr-spark svg { display: block; overflow: visible; }
.cr-spark .cr-empty { padding: var(--space-2); font-size: 12px; }
.cr-spark-ends { display: flex; justify-content: space-between; gap: var(--space-2); margin: var(--space-1) 0 0; font: 500 11px/1.3 var(--font-mono); color: var(--text-muted); }
.cr-spark-ends span { display: flex; flex-direction: column; white-space: nowrap; }
.cr-spark-ends span:last-child { text-align: right; }
.cr-spark-ends i { font: 400 10.5px/1.3 var(--font-body); font-style: normal; }
.cr-spark-ends b { font-weight: 500; color: var(--heading); }

/* ---------- charts ---------- */
.cr-chart { position: relative; min-height: 15rem; min-width: 0; }
.cr-chart-tall { min-height: 20rem; }
.cr-chart[hidden] { display: none; }
.cr-chart svg { display: block; overflow: visible; }
.cr-chart text, .cr-brush text, .cr-vs-bar text { font-family: var(--font-body); font-size: 12px; fill: var(--body); }
.cr-chart .cr-axis-title { font: 600 11.5px/1 var(--font-head); fill: var(--text-muted); letter-spacing: .02em; }
.cr-chart .cr-end-label { font: 600 12px/1 var(--font-head); fill: var(--heading); }
.cr-grid-lines line { stroke: var(--divider); stroke-opacity: .7; }
.cr-grid-lines .domain, .cr-axis .domain { display: none; }
.cr-axis line { stroke: var(--divider); }
.cr-legend { display: flex; flex-wrap: wrap; gap: var(--space-1) var(--space-4); margin: var(--space-2) 0 0; font-size: 12.5px; color: var(--heading); }
.cr-legend span { display: inline-flex; align-items: center; gap: var(--space-2); }
.cr-swatch { display: inline-block; width: 12px; height: 12px; border-radius: var(--radius-xs); flex: none; }
.cr-swatch.cr-swatch-stroke { width: 22px; height: 8px; border-radius: 0; overflow: visible; }
.cr-swatch.cr-dot { width: 10px; height: 10px; border-radius: 50%; }
.cr-swatch.cr-ring { box-sizing: border-box; border: 2px solid; }
.cr-tip { position: absolute; z-index: 5; pointer-events: none; max-width: 300px; padding: var(--space-2) var(--space-3); border-radius: var(--radius-sm);
  background: var(--ink-900); color: #ffffff; font: 500 12px/1.45 var(--font-body); box-shadow: 0 4px 12px rgb(0 0 0 / .25); }
.cr-tip[hidden] { display: none; }
.cr-tip-head { font-weight: 700; margin-bottom: var(--space-1); }
.cr-tip-media { display: flex; gap: var(--space-2); align-items: flex-start; }
.cr-tip-media img { width: 44px; height: 55px; object-fit: cover; border-radius: var(--radius-xs); flex: none; }
.cr-tip-row { display: flex; align-items: center; gap: var(--space-2); }
.cr-tip .cr-swatch { width: 10px; height: 10px; }
.cr-hit { cursor: pointer; }
.cr-heat-scroll { overflow-x: auto; min-width: 0; }
