  min-height: calc(64px + var(--space-3)); }
.cr-ph-words { display: flex; flex-direction: column; min-width: 0; }
.cr-thumb { flex: none; width: 64px; height: 64px; border-radius: var(--radius); object-fit: cover; border: 1px solid var(--border); }
.cr-ph-image { font: 400 11.5px/1.3 var(--font-body); color: var(--text-muted); }
