.cr-g-unknown::before { content: "?"; inset: 0; display: grid; place-items: center; font: 700 20px/1 var(--font-head); color: var(--text-muted); }
.cr-fmt { position: absolute; left: var(--space-2); bottom: var(--space-2); z-index: 1; padding: var(--space-half) var(--space-2); border-radius: var(--radius-xs);
