.cr-ad-body { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-3); min-width: 0; flex: 1; }
.cr-ad-top { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); }
.cr-flag { padding: var(--space-half) var(--space-2); border-radius: var(--radius-pill); border: 1px dashed var(--divider); font: 600 11px/1.4 var(--font-head); color: var(--text-muted); }
.cr-ad-title { margin: 0; font: 600 13.5px/1.35 var(--font-head); color: var(--heading); overflow-wrap: break-word; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; min-height: 2lh; }
.cr-ad-stats { display: flex; justify-content: space-between; gap: var(--space-2); margin: 0; font-size: 12px; color: var(--text-muted); }
