/* ---------- verdict chips ---------- */
.cr-chip { display: inline-block; width: fit-content; padding: var(--space-half) var(--space-2); border-radius: var(--radius-pill); border: 1px solid var(--divider);
  font: 600 11px/1.4 var(--font-head); white-space: nowrap; color: var(--text); background: var(--chip-bg); }
.cr-v-scale { background: var(--v-scale-bg); color: var(--v-scale-fg); border-color: var(--v-scale-bd); }
.cr-v-keep { background: var(--v-keep-bg); color: var(--v-keep-fg); border-color: var(--v-keep-bd); }
.cr-v-iterate { background: var(--v-iterate-bg); color: var(--v-iterate-fg); border-color: var(--v-iterate-bd); }
.cr-v-check { background: var(--v-check-bg); color: var(--v-check-fg); border-color: var(--v-check-bd); }
