.cr-conf { padding: var(--space-half) var(--space-2); border-radius: var(--radius-pill); border: 1px solid var(--divider); font: 600 11.5px/1.5 var(--font-head); color: var(--text-muted); }
.cr-chips { display: flex; flex-wrap: wrap; gap: var(--space-2); align-items: center; margin: 0; }

/* ---------- ad detail ---------- */
.cr-back { align-self: flex-start; font: 600 13px/1 var(--font-head); color: var(--accent); background: none; border: 0; padding: var(--space-1) 0; cursor: pointer; }
