.cr-dstat b { font: 500 16px/1.3 var(--font-mono); color: var(--text); overflow-wrap: anywhere; }
.cr-versus { display: grid; grid-template-columns: minmax(6rem, max-content) minmax(5rem, max-content) minmax(10rem, 1fr); gap: var(--space-1) var(--space-4); align-items: center; font-size: 13px; }
.cr-vs-name { color: var(--text-muted); }
