.cr-vs-bar { position: relative; height: 34px; min-width: 0; }
.cr-vs-bar svg { display: block; overflow: visible; }
.cr-vs-bar .cr-vs-tick { font: 500 10.5px/1 var(--font-mono); fill: var(--text-muted); }
.cr-vs-group { grid-column: 1 / -1; margin: 0 0 var(--space-2); font-size: 11.5px; color: var(--text-muted); border-bottom: 1px solid var(--border); padding-bottom: var(--space-2); }

/* ---------- tables ---------- */
.cr-scroll { overflow-x: auto; min-width: 0; border: 1px solid var(--divider); border-radius: var(--radius); }
.cr-scroll[hidden] { display: none; }
