.cr-track-dot { overflow: visible; height: 4px; }
.cr-track-tick { position: absolute; top: -6px; width: 2px; height: 16px; margin-left: -1px; background: var(--heading); border-radius: 1px; }
.cr-fmt-scale { display: flex; flex-direction: column; gap: 2px; }
