.cr-fill { display: block; height: 100%; border-radius: var(--radius-pill); }
.cr-barval { flex: none; font-family: var(--font-mono); min-width: 5.5rem; text-align: right; font-weight: 600; white-space: nowrap; }
.cr-board td.num { min-width: 14rem; }
