.cr-fmt-row { display: grid; grid-template-columns: minmax(9rem, 1.1fr) minmax(0, 1.4fr) minmax(0, 1fr); gap: var(--space-4); align-items: center; padding: var(--space-2) 0;
  border-bottom: 1px solid color-mix(in srgb, var(--border) 60%, transparent); font-size: 13px; }
