.cr-gdot-inline { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: var(--space-1); vertical-align: middle; }
.cr-grade-best { background: var(--up-fg); }
.cr-grade-mid { background: var(--text-muted); }
