.cr-gap-chip b { color: var(--accent-text); }
.cr-briefs { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 22rem), 1fr)); gap: var(--space-3); }
.cr-briefs[hidden] { display: none; }
.cr-brief { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--pad-card); border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); min-width: 0; }
