.cr-ref { padding: var(--space-half) var(--space-2); border-radius: var(--radius-pill); background: var(--surface-muted); font-size: 12px; color: var(--heading); max-width: 100%; overflow-wrap: anywhere; }

/* ---------- stats ---------- */
