  .cr-scope-seg dt { font-size: 12px; }
  .cr-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-2); }
  .cr-kpi { padding: var(--space-3); }
  .cr-kpi-value { font-size: 19px; }
  .cr-kpi.cr-unknown { grid-column: span 1; }
  .cr-card { padding: var(--space-4); }
  .cr-versus { grid-template-columns: minmax(0, 1fr) max-content; }
  .cr-vs-bar { grid-column: 1 / -1; }
  .cr-brief-facts { grid-template-columns: minmax(0, 1fr); }
  .cr-search { max-width: none; }
}
